<?php
ini_set('display_errors',0);error_reporting(E_ALL);session_start();require_once __DIR__ . '/../lead-engine/config.php';if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function sbm8($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>20]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return['ok'=>$http>=200&&$http<300,'http'=>$http,'data'=>is_array($d)?$d:[],'body'=>$b];}function tel8($p){$d=preg_replace('/\D+/','',(string)$p);if(strlen($d)===10)return'+1'.$d;if(strlen($d)===11&&substr($d,0,1)==='1')return'+'.$d;return$p;}$msg='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){$id=$_POST['id']??'';$status=$_POST['status']??'';if($id&&in_array($status,['queued','called','booked','skipped','done'],true)){$r=sbm8('PATCH','jessica_priority_queue?id=eq.'.rawurlencode($id),['status'=>$status,'updated_at'=>date('c')]);$msg=$r['ok']?'Mission updated.':'Update failed: '.$r['body'];}}$status=$_GET['status']??'pending';$endpoint=$status==='all'?'jessica_priority_queue?select=*&order=priority_score.desc&limit=300':'jessica_priority_queue?select=*&status=eq.'.rawurlencode($status).'&order=priority_score.desc&limit=300';$res=sbm8('GET',$endpoint);$rows=$res['data'];if(!$res['ok'])$error=$res['body'];$mission=[];$towns=[];$hot=0;$book=0;foreach($rows as $r){$m=$r['mission_type']?:'UNKNOWN';$mission[$m]=($mission[$m]??0)+1;$t=$r['town']?:'Unknown';$towns[$t]=($towns[$t]??0)+1;if((int)$r['priority_score']>=100)$hot++;if($m==='BOOK_APPOINTMENT')$book++;}arsort($towns);$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';}catch(Throwable $e){$rows=[];$mission=[];$towns=[];$hot=0;$book=0;$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';$error='PHP exception: '.$e->getMessage().' on line '.$e->getLine();}
?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jessica Mission Control V8</title><style>body{margin:0;background:#f5f3ef;color:#10101a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.header{background:linear-gradient(135deg,#10101a,#1a1a2e);color:#fff;padding:30px}.brand{font-family:Georgia,serif;color:#c8a96e;font-size:36px}.wrap{max-width:1450px;margin:auto;padding:26px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.kpi,.panel{background:#fff;border-radius:16px;box-shadow:0 2px 12px #0001}.kpi{padding:18px}.n{font-size:34px;font-weight:900}.panel{margin-top:18px;overflow:hidden}.panel h2{font-family:Georgia,serif;margin:0;padding:18px;border-bottom:1px solid #eee}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:14px;vertical-align:top}th{font-size:11px;text-transform:uppercase;color:#777;background:#faf9f6}.badge{border-radius:999px;padding:5px 8px;font-size:11px;text-transform:uppercase}.hot{background:#2b2110;color:#ffd36b}.high{background:#fff4d7;color:#8a5a00}.normal{background:#e9f2ff;color:#174ea6}.btn{display:inline-block;border:0;background:#10101a;color:#fff;text-decoration:none;padding:8px 10px;border-radius:8px;font-size:12px;font-weight:800;margin:2px;cursor:pointer}.gold{background:#c8a96e;color:#111}.light{background:#f2efe8;color:#111}.layout{display:grid;grid-template-columns:1fr .4fr;gap:18px}.muted{color:#777;font-size:13px}.err{background:#ffeaea;color:#9b1c1c;padding:14px;border-radius:12px;margin:12px 0;white-space:pre-wrap}@media(max-width:900px){.grid,.layout{grid-template-columns:1fr}.wrap{padding:14px}}</style></head><body><div class="header"><div class="brand">Jessica Mission Control V8</div><div>Daily mission queue · autonomous prioritization · <a style="color:#fff" href="/dashboard/operations.php">Operations</a></div></div><main class="wrap"><?php if($msg):?><div class="panel" style="padding:16px"><?=h($msg)?></div><?php endif;?><?php if($error):?><div class="err"><?=h($error)?></div><?php endif;?><p><a class="btn gold" href="/lead-engine/build-jessica-priority-queue.php?key=<?=h($cronKey)?>" target="_blank">Build Jessica Mission Now</a> <a class="btn light" href="?status=pending">Pending</a> <a class="btn light" href="?status=all">All</a></p><section class="grid"><div class="kpi"><div class="n"><?=h(count($rows))?></div>Total Loaded</div><div class="kpi"><div class="n"><?=h($hot)?></div>100+ Priority</div><div class="kpi"><div class="n"><?=h($book)?></div>Book Appt</div><div class="kpi"><div class="n"><?=h(count($mission))?></div>Mission Types</div></section><div class="layout"><section class="panel"><h2>Today's Top Mission Queue</h2><table><tr><th>Priority</th><th>Lead</th><th>Mission</th><th>Why</th><th>Action</th></tr><?php foreach($rows as $r):$score=(int)$r['priority_score'];$cls=$score>=100?'hot':($score>=85?'high':'normal');?><tr><td><span class="badge <?=h($cls)?>"><?=h($score)?></span><div class="muted"><?=h($r['confidence'])?></div></td><td><strong><?=h($r['name']?:'Unknown')?></strong><div class="muted"><?=h($r['phone'])?><br><?=h($r['email'])?><br><?=h($r['town'])?> · <?=h($r['source'])?></div></td><td><strong><?=h($r['mission_type'])?></strong><div class="muted">Call by: <?=h($r['call_by'])?></div></td><td><?=h($r['reason'])?><div class="muted"><?=h($r['suggested_action'])?></div></td><td><?php if($r['phone']):?><a class="btn gold" href="tel:<?=h(tel8($r['phone']))?>">Call</a><?php endif;?><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn light" name="status" value="queued">Queue</button></form><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn" name="status" value="called">Called</button></form><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn gold" name="status" value="booked">Booked</button></form><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn light" name="status" value="done">Done</button></form></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Mission Breakdown</h2><table><tr><th>Mission</th><th>Count</th></tr><?php foreach($mission as $m=>$c):?><tr><td><?=h($m)?></td><td><?=h($c)?></td></tr><?php endforeach;?></table><h2>Town Priority</h2><table><tr><th>Town</th><th>Count</th></tr><?php foreach(array_slice($towns,0,20,true) as $t=>$c):?><tr><td><?=h($t)?></td><td><?=h($c)?></td></tr><?php endforeach;?></table></section></div></main></body></html>
